theorem check_cell_sound {m : ℕ} {cs : List NodeEnclosure}
    (hc : check m cs = true) {k : ℕ} (hk : k + 1 < cs.length) {s : ℝ}
    (hs : s ∈ Icc (grid m k : ℝ) (grid m (k + 1) : ℝ)) :
    ((entry cs k).lower : ℝ) / s ≤ buchstab s ∧
      buchstab s ≤ ((entry cs (k + 1)).upper : ℝ) / s :=
